import traceback

def ratio(a, b):
    return a / b

def run():
    return ratio(1, 0)

try:
    run()
except Exception as e:
    frames = traceback.extract_tb(e.__traceback__)
    print(f"{type(e).__name__} in {frames[-1].name}")
    print(" <- ".join(f.name for f in reversed(frames)))

assert frames[-1].name == 'ratio'
assert [f.name for f in frames] == ['<module>', 'run', 'ratio']
